//! Generates the TypeScript SDK in `sdk/typescript/` from the API's own
//! `OpenAPI` document (task 1.20, KH-API-4).
//!
//! The SDK has two generated files. `src/schema.d.ts` holds one type per
//! schema and the `Operations` interface: what each operation takes and
//! answers. `src/operations.js` holds where each operation is sent. The
//! hand-written client in `src/index.js` reads both, so no API type in the
//! SDK is written by hand.

mod types;

use serde_json::Value;

/// The header every generated file starts with.
const HEADER: &str = "// Generated by the khalid-sdk crate from openapi.json. Do not edit by hand.\n\
// To refresh it, run: cargo nextest run -p khalid-sdk\n\n";

/// Why the SDK could not be generated from a document.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum SdkError {
    /// The document is not JSON.
    #[error("the OpenAPI document is not JSON")]
    NotJson(#[source] serde_json::Error),
    /// The document has no `paths` or no `components.schemas` object.
    #[error("the OpenAPI document has no {0} object")]
    Missing(&'static str),
    /// An operation has no `operationId`, so it has no name in the SDK.
    #[error("the operation {method} {path} has no operationId")]
    NoOperationId {
        /// The operation's method, such as `get`.
        method: String,
        /// The operation's path template.
        path: String,
    },
    /// Two operations share one `operationId`.
    #[error("two operations are named {0}")]
    DuplicateOperation(String),
    /// A `$ref` points somewhere other than `#/components/schemas/`.
    #[error("the reference {0} does not point at a schema in #/components/schemas")]
    Reference(String),
    /// A schema or operation name cannot be a TypeScript name.
    #[error("{0} cannot be a TypeScript name")]
    Name(String),
    /// A request body has a media type the client cannot send.
    #[error("the operation {operation} takes a {media} body, which the client cannot send")]
    MediaType {
        /// The operation's `operationId`.
        operation: String,
        /// The body's media type.
        media: String,
    },
}

/// One file of the SDK, with its path inside `sdk/typescript/`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedFile {
    /// Where the file goes, relative to `sdk/typescript/`.
    pub path: &'static str,
    /// What the file holds.
    pub contents: String,
}

/// Generates the SDK's files from the `OpenAPI` document in `document`.
///
/// The output depends only on the document, so the same document always
/// gives the same bytes.
///
/// # Errors
///
/// Returns [`SdkError`] when the document is not JSON, lacks `paths` or
/// `components.schemas`, names an operation twice or not at all, points a
/// `$ref` outside the schemas, uses a name TypeScript cannot hold, or takes
/// a body the client cannot send.
pub fn generate(document: &str) -> Result<Vec<GeneratedFile>, SdkError> {
    let document: Value = serde_json::from_str(document).map_err(SdkError::NotJson)?;
    let schemas = document
        .pointer("/components/schemas")
        .and_then(Value::as_object)
        .ok_or(SdkError::Missing("components.schemas"))?;
    let mut schema = String::from(HEADER);
    schema.push_str(&types::declarations(schemas)?);
    Ok(vec![GeneratedFile {
        path: "src/schema.d.ts",
        contents: schema,
    }])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_document_that_is_not_json_is_refused() {
        assert!(matches!(generate("{"), Err(SdkError::NotJson(_))));
    }

    #[test]
    fn a_document_without_schemas_is_refused() {
        let got = generate(r#"{"paths": {}}"#);
        assert!(matches!(got, Err(SdkError::Missing("components.schemas"))));
    }

    #[test]
    fn the_same_document_gives_the_same_files() {
        let document = r#"{"paths": {}, "components": {"schemas": {"Tag": {"type": "string"}}}}"#;
        let first = generate(document).unwrap();
        assert_eq!(first, generate(document).unwrap());
        let paths: Vec<&str> = first.iter().map(|file| file.path).collect();
        assert_eq!(paths, ["src/schema.d.ts"]);
        assert!(
            first[0].contents.starts_with(HEADER),
            "{}",
            first[0].contents
        );
        assert!(first[0].contents.contains("export type Tag = string;\n"));
    }
}
